# python3 claude-edition/test/make_dense_deck.py <out.pdf> — a dense, realistic slide lecture (renal physiology, 20 slides, 13 sections running over several slides): values, steps, comparisons, mechanisms
import sys
from reportlab.lib.pagesizes import landscape, A4
from reportlab.pdfgen import canvas
S = [
 ('Lecture 7: Renal Physiology', ['Dr. Example Lecturer', 'Department of Physiology, Year 2']),
 ('Learning Objectives', ['- Describe the parts of the nephron', '- Explain glomerular filtration and its regulation', '- Explain hormonal control of water and sodium']),
 ('Nephron Structure (1/2)', ['- Each human kidney contains about one million nephrons.', '- A nephron consists of a renal corpuscle and a renal tubule.', '- The renal corpuscle is formed by the glomerulus and Bowman\'s capsule.', '- Podocytes of the visceral layer wrap the glomerular capillaries with foot processes.']),
 ('Nephron Structure (2/2)', ['- The renal tubule runs from the proximal convoluted tubule to the loop of Henle and the distal convoluted tubule.', '- Cortical nephrons make up about 85% of all nephrons and have short loops of Henle.', '- Juxtamedullary nephrons have long loops that reach deep into the medulla.', '- Juxtamedullary nephrons create the concentration gradient needed for concentrated urine.']),
 ('Glomerular Filtration', ['- The normal glomerular filtration rate (GFR) is about 125 mL per minute.', '- About 180 litres of filtrate are formed every day, and about 99% of it is reabsorbed.', '- The filtration barrier has three layers: fenestrated endothelium, basement membrane and podocyte filtration slits.', '- Plasma proteins such as albumin are normally kept out of the filtrate by size and negative charge.']),
 ('Glomerular Filtration (continued)', ['- Net filtration pressure equals glomerular hydrostatic pressure minus capsular hydrostatic pressure and plasma oncotic pressure.', '- Glomerular hydrostatic pressure of about 55 mmHg is the main force that drives filtration.', '- Plasma oncotic pressure of about 30 mmHg opposes filtration.', '- Constriction of the afferent arteriole lowers GFR, whereas constriction of the efferent arteriole raises it.']),
 ('Regulation of GFR', ['- In the myogenic mechanism, a stretched afferent arteriole contracts and keeps GFR stable.', '- In tubuloglomerular feedback, the macula densa senses sodium chloride in the distal tubule.', '- High sodium chloride at the macula densa constricts the afferent arteriole and lowers GFR.', '- Autoregulation keeps GFR nearly constant when mean arterial pressure is between 80 and 180 mmHg.']),
 ('Tubular Reabsorption - Part 1', ['- The proximal convoluted tubule reabsorbs about 65% of the filtered sodium and water.', '- Glucose is reabsorbed in the proximal tubule by sodium-glucose cotransporters (SGLT2).', '- Glucose appears in the urine when plasma glucose exceeds the renal threshold of about 180 mg/dL.', '- Amino acids are almost completely reabsorbed in the proximal tubule.']),
 ('Tubular Reabsorption - Part 2', ['- The descending limb of the loop of Henle is permeable to water but not to solutes.', '- The thick ascending limb pumps sodium, potassium and chloride out through the NKCC2 cotransporter.', '- The thick ascending limb is impermeable to water, so the tubular fluid becomes dilute.', '- Loop diuretics such as furosemide block the NKCC2 cotransporter.']),
 ('Countercurrent Multiplication', ['- The loop of Henle builds a medullary osmotic gradient from about 300 to 1200 mOsm/kg.', '- Urea recycling from the collecting duct adds to the gradient of the inner medulla.', '- The vasa recta preserve the gradient by countercurrent exchange.', '- Without the gradient, the kidney cannot produce concentrated urine.']),
 ('Hormonal Control: ADH', ['- Antidiuretic hormone (ADH) is released from the posterior pituitary when plasma osmolality rises.', '- ADH inserts aquaporin-2 channels into the apical membrane of collecting duct cells.', '- With high ADH, urine can be concentrated up to about 1200 mOsm/kg.', '- Lack of ADH action causes diabetes insipidus with large volumes of dilute urine.']),
 ('Hormonal Control: RAAS', ['- Juxtaglomerular cells release renin when renal perfusion pressure falls.', '- Renin converts angiotensinogen into angiotensin I.', '- Angiotensin-converting enzyme in the lungs converts angiotensin I into angiotensin II.', '- Angiotensin II constricts arterioles and stimulates aldosterone release from the adrenal cortex.']),
 ('Hormonal Control: RAAS (continued)', ['- Aldosterone increases sodium reabsorption and potassium secretion by principal cells of the collecting duct.', '- Atrial natriuretic peptide is released when the atria are stretched and increases sodium excretion.', '- Atrial natriuretic peptide opposes the actions of the renin-angiotensin-aldosterone system.']),
 ('Potassium Handling', ['- Most filtered potassium is reabsorbed before the distal tubule.', '- Principal cells secrete potassium under the influence of aldosterone.', '- High dietary potassium increases potassium secretion in the collecting duct.', '- Hyperkalaemia stimulates aldosterone release directly.']),
 ('Acid-Base Regulation', ['- The kidney reabsorbs filtered bicarbonate, mainly in the proximal tubule.', '- Intercalated cells of type A secrete hydrogen ions into the tubular fluid.', '- Secreted hydrogen ions are buffered by phosphate and by ammonia.', '- In chronic acidosis the kidney increases ammonium production.']),
 ('Renal Clearance', ['- Clearance is the volume of plasma completely cleared of a substance per minute.', '- Inulin clearance equals GFR because inulin is filtered but neither reabsorbed nor secreted.', '- Creatinine clearance is used in practice to estimate GFR.', '- PAH clearance is used to estimate renal plasma flow.']),
 ('Micturition', ['- Urine moves from the renal pelvis to the bladder by peristalsis of the ureters.', '- Stretch of the bladder wall triggers the micturition reflex.', '- Parasympathetic stimulation contracts the detrusor muscle.', '- The external urethral sphincter is under voluntary control.']),
 ('Clinical Correlations', ['- Proteinuria indicates damage to the glomerular filtration barrier.', '- A falling GFR leads to a rise in plasma creatinine.', '- Dehydration raises ADH and produces a small volume of concentrated urine.', '- Renal artery stenosis activates the renin-angiotensin-aldosterone system and raises blood pressure.']),
 ('Summary', ['- The nephron filters plasma, then reabsorbs and secretes to form urine.', '- GFR is kept stable by the myogenic mechanism and tubuloglomerular feedback.', '- ADH controls water, aldosterone controls sodium and potassium.']),
 ('References', ['Guyton and Hall Textbook of Medical Physiology, 14th edition.', 'Boron and Boulpaep, Medical Physiology, 3rd edition.']),
]
c = canvas.Canvas(sys.argv[1], pagesize=landscape(A4)); W, H = landscape(A4)
for title, lines in S:
    c.setFont('Helvetica-Bold', 24); c.drawString(50, H - 80, title); c.setFont('Helvetica', 14); y = H - 130
    for l in lines:
        while len(l) > 105: k = l.rfind(' ', 0, 105); c.drawString(60, y, l[:k]); y -= 24; l = '  ' + l[k + 1:]
        c.drawString(60, y, l); y -= 30
    c.showPage()
c.save(); print(sys.argv[1], len(S), 'slides')
